import {sb} from './supabase.js';
import {REQUIRE_EMAIL_OTP,OTP_LENGTH} from './config.js';
function navFor(k){const a=[['layout-dashboard','Dashboard'],['folder','Projects'],['list-checks','Tasks'],['git-branch','Sprints'],['columns','Kanban'],['bar-chart-3','Analytics']];if(k=='admin'||k=='pm')a.push(['network','Teams']);if(k=='admin')a.push(['users','Users']);a.push(['settings','Settings']);return a}
const ROLES={
admin:{db:'admin',n:'Admin',i:'shield-check',c:'#8b5cf6',d:'System management, user administration and permissions.',nav:navFor('admin'),tiles:[['w6','activity','System status','No status reported','Service health will be shown from the live API.']]},
pm:{db:'project_manager',n:'Project Manager',i:'briefcase',c:'#f59e0b',d:'Project creation, planning and team coordination.',nav:navFor('pm'),tiles:[['w3','folder','Project overview','No projects yet','Create your first project to start planning sprints.'],['w6','plus-circle','Project creation','Start a project','Project creation arrives in the next milestone step.']]},
dev:{db:'developer',n:'Developer',i:'code-2',c:'#3b82f6',d:'Development work and assigned project tasks.',nav:navFor('dev'),tiles:[['w3','folder','Assigned projects','Nothing assigned','Projects assigned by a Project Manager show up here.'],['w3','list-checks','Assigned tasks','No tasks yet','Task progress updates will be available here.']]},
tester:{db:'tester',n:'Tester',i:'bug',c:'#10b981',d:'Application testing and bug reporting.',nav:navFor('tester'),tiles:[['w3','flask-conical','Testing assignments','No assignments','Assigned test cycles will appear here.'],['w3','activity','Testing overview','No results yet','Executed test results will be summarised here.']]},
devops:{db:'devops',n:'DevOps Engineer',i:'server',c:'#06b6d4',d:'Build, deployment and infrastructure management.',nav:navFor('devops'),tiles:[['w3','git-branch','Build pipelines','No pipelines connected','Pipeline status arrives with the build integration.'],['w3','rocket','Deployments','No deployments','Deployment history will be listed here.']]}};
const K=Object.keys(ROLES);
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const root=$('#root');let cur={role:'admin'};
const ico=()=>window.lucide&&lucide.createIcons();
const I=(n,c='ic')=>`<i data-lucide="${n}" class="${c}"></i>`;
function toast(msg,t='in'){const e=document.createElement('div');e.className='toast '+t;e.innerHTML=I(t=='ok'?'check-circle-2':t=='er'?'alert-circle':'info')+'<span>'+msg+'</span>';$('#toasts').appendChild(e);ico();setTimeout(()=>e.remove(),4200)}
function theme(){const d=document.documentElement;d.dataset.theme=d.dataset.theme=='light'?'dark':'light'}
if(matchMedia('(prefers-color-scheme: light)').matches)document.documentElement.dataset.theme='light';
function topbar(){return `<header class="top glass"><a href="#landing" class="logo">${'<span class="m">'+I('network')+'</span>'}NeuroForge Nexus</a><nav><a class="nb" href="#landing">Home</a><button class="nb" data-dlg="about">About</button><button class="nb" data-dlg="help">Help</button></nav><button class="ib" data-act="cmd" aria-label="Open command menu">${I('search')}</button><button class="ib" data-act="theme" aria-label="Toggle theme">${I('sun-moon')}</button><button class="pri" data-act="signin">Sign in</button></header>`}
function landing(){return topbar()+`<section class="hero"><h1>One Platform. Five Roles. One Connected Workflow.</h1><p>Enterprise Software Lifecycle and DevOps Management System: plan, build, test, release and monitor software in one place.</p></section><section class="grid" id="roles">${K.map(k=>{const r=ROLES[k];return `<button class="rc glass" style="--c:${r.c}" data-role="${k}"><span class="ri">${I(r.i)}</span><h3>${r.n}</h3><p>${r.d}</p><span class="go">Continue ${I('arrow-right')}</span></button>`}).join('')}</section>`}
function login(k){const r=ROLES[k];cur.role=k;return `<div class="center" style="--rc:${r.c}"><div class="card glass"><a class="lnk" href="#landing" style="display:inline-flex;gap:6px;align-items:center;font-size:13px">${I('arrow-left')} Back to roles</a><div style="margin-top:18px"><span class="badge">${I(r.i)} ${r.n}</span></div><h2>Welcome back</h2><p class="sub">Sign in to your ${r.n} workspace.</p><form id="lf" novalidate><div id="g1"><label for="em">Email</label><input id="em" type="email" autocomplete="email" placeholder="you@company.com"><div class="err" id="e1"></div></div><div id="g2"><label for="pw">Password</label><div class="fld"><input id="pw" type="password" autocomplete="current-password" placeholder="Enter your password"><button type="button" class="ib" data-act="eye" aria-label="Show password">${I('eye')}</button></div><div class="err" id="e2"></div></div><div class="row"><span></span><button type="button" class="lnk" data-dlg="forgot">Forgot password?</button></div><button class="pri full" id="sb">Sign In</button></form>${k=='admin'?'<p class="foot">Admin accounts are provisioned by an authorized administrator.</p>':'<p class="foot">New here? <button class="lnk" data-dlg="reg">Request access</button></p>'}</div></div>`}
let tmr,cd;
function otp(){const r=ROLES[cur.role];return `<div class="center" style="--rc:${r.c}"><div class="card glass" style="text-align:center"><div class="shield">${I('shield-check')}</div><h2 style="margin-top:0">Verify your email</h2><p class="sub" style="margin-bottom:0">Enter the ${OTP_LENGTH}-digit code sent to <b id="oe"></b>. It expires in <b id="ct">5:00</b>.</p><div class="otp" id="ob">${Array.from({length:OTP_LENGTH},(_,i)=>i).map(i=>`<input inputmode="numeric" maxlength="1" placeholder=" " aria-label="Digit ${i+1}" autocomplete="one-time-code">`).join('')}</div><div class="err" id="oer" style="margin:-10px 0 12px"></div><button class="pri full" id="ov" disabled>Verify Code ${I('arrow-right')}</button><p class="foot"><button class="lnk" id="rs" disabled>Resend code in 60s</button> · <a class="lnk" href="#login-${cur.role}">Change email</a></p></div></div>`}
function dash(k){const r=ROLES[k];cur.role=k;const d=new Date().toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});return `<div class="app" style="--rc:${r.c}"><aside class="glass" id="sd"><div class="logo"><span class="m">${I('network')}</span>NeuroForge</div>${r.nav.map((n,i)=>`<button class="ni ${i?'':'on'}" data-nav="${n[1]}">${I(n[0])}${n[1]}</button>`).join('')}<button class="me" data-act="out"><span class="av">${esc((cur.me.full_name||r.n)[0])}</span><span style="flex:1"><b style="display:block;font-size:13px">${esc(cur.me.full_name||cur.me.email)}</b><span style="font-size:12px;color:var(--mut)">Sign out</span></span>${I('log-out')}</button></aside><main><div class="bar glass"><button class="ib menu" data-act="menu" aria-label="Menu">${I('menu')}</button><h2>${r.n} Dashboard</h2><button class="pill d" data-act="cmd">${I('search')} Search <span class="kbd">Ctrl K</span></button><span class="pill d">${d}</span><button class="ib" data-act="theme" aria-label="Toggle theme">${I('sun-moon')}</button><button class="ib" data-act="bell" aria-label="Notifications">${I('bell')}</button></div><div class="tiles"><div class="stats full" id="stt"></div><section class="tile glass w6" id="pt"><h4>${I('folder')}Projects<span style="margin-left:auto">${CAN()?'<button class="pri" id="np">'+'New project</button>':''}</span></h4><div id="pl" class="empty">Loading…</div></section>${CAN()?'<section class="tile glass w6" id="tmt"><h4>'+I('network')+'Teams<span style="margin-left:auto"><button class="pri" id="nteam">New team</button></span></h4><div id="tl" class="empty">Loading…</div></section>':''}${k=='admin'?'<section class="tile glass w6"><h4>'+I('users')+'User management</h4><div id="ul" class="empty">Loading…</div></section><section class="tile glass w6"><h4>'+I('key-round')+'Roles and permissions</h4><div id="rpl" class="empty">Loading…</div></section>':''}${r.tiles.filter(t=>t[1]!=='folder'&&t[1]!=='plus-circle').map(t=>`<section class="tile glass ${t[0]}"><h4>${I(t[1])}${t[2]}</h4><div class="empty">${I(t[1])}<b>${t[3]}</b><span>${t[4]}</span></div></section>`).join('')}</div></main></div>`}
async function route(){const h=location.hash.slice(1)||'landing';let html;if(h.startsWith('dash-')&&ROLES[h.slice(5)]){const me=await guard(h.slice(5));if(!me){location.hash='landing';return}cur.me=me}
 if(h.startsWith('login-')&&ROLES[h.slice(6)])html=login(h.slice(6));
 else if(h.startsWith('board-')){const me=await guardAny();if(!me){location.hash='landing';return}cur.me=me;html=boardShell()}
 else if(h=='otp')html=otp();
 else if(h.startsWith('dash-')&&ROLES[h.slice(5)])html=dash(h.slice(5));
 else html=landing();
 clearInterval(tmr);root.innerHTML='<div class="view on">'+html+'</div>';ico();bind(h);scrollTo(0,0)}
function bind(h){
 if(h=='otp')initOtp();if(h=='dash-admin')loadUsers();if(h.startsWith('dash-')){loadProjects();loadStats();if(CAN())loadTeams();if(h=='dash-admin')loadRoles()}if(h.startsWith('board-'))loadBoard(h.slice(6));
 $$('.rc').forEach(c=>c.addEventListener('pointermove',e=>{const b=c.getBoundingClientRect();c.style.setProperty('--mx',e.clientX-b.left+'px');c.style.setProperty('--my',e.clientY-b.top+'px')}));
 const lf=$('#lf');if(lf)lf.addEventListener('submit',submitLogin);
 if(lf)$('#em').addEventListener('input',()=>clr('g1','e1'));if(lf)$('#pw').addEventListener('input',()=>clr('g2','e2'));
}
const clr=(g,e)=>{$('#'+g).classList.remove('bad');$('#'+e).textContent=''};
const bad=(g,e,m)=>{const x=$('#'+g);x.classList.remove('bad');void x.offsetWidth;x.classList.add('bad');$('#'+e).textContent=m};
const mailRe=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function submitLogin(e){e.preventDefault();const em=$('#em').value.trim(),pw=$('#pw').value;let ok=true;
 if(!em){bad('g1','e1','Email is required.');ok=false}else if(!mailRe.test(em)){bad('g1','e1','Enter a valid email address.');ok=false}
 if(!pw){bad('g2','e2','Password is required.');ok=false}if(!ok){toast('Please fix the highlighted fields.','er');return}
 doLogin(em,pw)}
function initOtp(){$('#oe').textContent=cur.email||'your email';const ins=$$('#ob input');ins[0].focus();
 ins.forEach((x,i)=>{x.addEventListener('input',()=>{x.value=x.value.replace(/\D/g,'');if(x.value&&ins[i+1])ins[i+1].focus()});
  x.addEventListener('keydown',e=>{if(e.key=='Backspace'&&!x.value&&ins[i-1]){ins[i-1].focus();ins[i-1].value=''}if(e.key=='ArrowLeft'&&ins[i-1])ins[i-1].focus();if(e.key=='ArrowRight'&&ins[i+1])ins[i+1].focus();if(e.key=='Enter')$('#ov').click()});
  x.addEventListener('paste',e=>{e.preventDefault();const t=(e.clipboardData.getData('text')||'').replace(/[\s-]/g,'');if(!isOtp(t)){$('#oer').textContent='The code must be exactly '+OTP_LENGTH+' digits.';return}[...t].forEach((c,j)=>ins[j].value=c);ins[ins.length-1].focus();upd()})});
 const upd=()=>{$('#ov').disabled=!isOtp(ins.map(i=>i.value).join(''))};ins.forEach(x=>{x.addEventListener('input',()=>{$('#oer').textContent='';upd()});x.addEventListener('keyup',upd)});upd();
 let left=300,cool=60;const ct=$('#ct'),rs=$('#rs');
 tmr=setInterval(()=>{left=Math.max(0,left-1);ct.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(cool>0){cool--;rs.textContent=cool?`Resend code in ${cool}s`:'Resend code';rs.disabled=cool>0}},1000);
 rs.onclick=async()=>{cool=60;rs.disabled=true;left=300;const r=cur.mode=='signup'?await sb.auth.resend({type:'signup',email:cur.email}):await sb.auth.signInWithOtp({email:cur.email,options:{shouldCreateUser:false}});toast(r.error?r.error.message:'A new code was sent.',r.error?'er':'ok')};
 $('#ov').onclick=()=>{const v=ins.map(i=>i.value).join('');if(!isOtp(v)){$('#oer').textContent='Enter all '+OTP_LENGTH+' digits.';$('#ob').classList.remove('bad');void $('#ob').offsetWidth;$('#ob').classList.add('bad');return}
  verifyCode(v)}}
/* dialogs */
function modal(html){const o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg" role="dialog" aria-modal="true">'+html+'</div>';const prev=document.activeElement;const close=()=>{o.remove();prev&&prev.focus&&prev.focus()};o.addEventListener('mousedown',e=>{if(e.target==o)close()});o.addEventListener('keydown',e=>{if(e.key=='Escape')close()});document.body.appendChild(o);ico();$$('[data-close]',o).forEach(b=>b.onclick=close);const f=$('input,button',o);f&&f.focus();return{o,close}}
const DL={about:()=>modal(`<h3>About NeuroForge Nexus</h3><p class="sub" style="color:var(--mut);margin:8px 0 18px">An enterprise software lifecycle and DevOps management system with five specialized roles.</p><button class="pri" data-close>Close</button>`),
help:()=>modal(`<h3>Help</h3><p style="color:var(--mut);margin:8px 0 18px">Pick your role, sign in, then verify the ${OTP_LENGTH}-digit code sent to your email. Press Ctrl+K (or Cmd+K) anywhere to open the command menu.</p><button class="pri" data-close>Got it</button>`),
forgot:()=>{const m=modal(`<h3>Reset your password</h3><p style="color:var(--mut);margin:6px 0 4px" id="fp">We will email a ${OTP_LENGTH}-digit recovery code.</p><div id="s1"><label for="fe">Email</label><input id="fe" type="email" placeholder="you@company.com"></div><div id="s2" style="display:none"><label for="fc">Code</label><input id="fc" type="text" inputmode="numeric" maxlength="6"><label for="fn">New password</label><input id="fn" type="password" placeholder="At least 8 characters"></div><div class="err" id="fer"></div><div style="display:flex;gap:10px;margin-top:18px"><button class="pri" id="fs">Send code</button><button class="sec" data-close>Cancel</button></div>`);
 const g=i=>$('#'+i,m.o);let step=1,em='';
 g('fs').onclick=async()=>{const e=g('fer');e.textContent='';g('fs').disabled=true;
  if(step==1){em=g('fe').value.trim();if(!mailRe.test(em)){e.textContent='Enter a valid email address.';g('fs').disabled=false;return}
   const {error}=await sb.auth.resetPasswordForEmail(em);g('fs').disabled=false;if(error){e.textContent=error.message;return}
   step=2;g('s1').style.display='none';g('s2').style.display='block';g('fs').textContent='Set new password';g('fp').textContent='Enter the code we emailed you and choose a new password.';return}
  if(g('fn').value.length<8){e.textContent='Password must be at least 8 characters.';g('fs').disabled=false;return}
  const v=await sb.auth.verifyOtp({email:em,token:g('fc').value.trim(),type:'recovery'});
  if(v.error){e.textContent='That code is invalid or has expired.';g('fs').disabled=false;return}
  const u=await sb.auth.updateUser({password:g('fn').value});await sb.auth.signOut({scope:'local'});g('fs').disabled=false;
  if(u.error){e.textContent=u.error.message;return}m.close();toast('Password updated. You can sign in now.','ok')}},
reg:()=>{const m=modal(`<h3>Request access</h3><p style="color:var(--mut);margin:6px 0 0">Role: <b>${ROLES[cur.role].n}</b>. An administrator approves new accounts.</p><label for="rn">Full name</label><input id="rn" type="text"><label for="re">Email</label><input id="re" type="email"><label for="rp">Password</label><input id="rp" type="password" placeholder="At least 8 characters"><div class="pbar" style="margin-top:6px"><i id="pwb" style="width:0"></i></div><div class="mut" id="pwt"></div><label for="rc">Confirm password</label><input id="rc" type="password"><label style="display:flex;gap:8px;align-items:center;font-weight:450"><input id="rt" type="checkbox"> I accept the terms and conditions</label><div class="err" id="rer"></div><div style="display:flex;gap:10px;margin-top:16px"><button class="pri" id="rb">Create account</button><button class="sec" data-close>Cancel</button></div>`);
 $('#rp',m.o).oninput=e=>{const v=e.target.value;const n=[v.length>=8,/[a-z]/.test(v)&&/[A-Z]/.test(v),/\d/.test(v),/[^A-Za-z0-9]/.test(v)].filter(Boolean).length;$('#pwb',m.o).style.width=(v?n*25:0)+'%';$('#pwt',m.o).textContent=v?['Weak','Weak','Fair','Good','Strong'][n]:''};
 $('#rb',m.o).onclick=async()=>{const g=i=>$('#'+i,m.o),e=g('rer');let msg='';
  if(!g('rn').value.trim())msg='Full name is required.';else if(!mailRe.test(g('re').value.trim()))msg='Enter a valid email address.';else if(g('rp').value.length<8)msg='Password must be at least 8 characters.';else if(g('rp').value!==g('rc').value)msg='Passwords do not match.';else if(!g('rt').checked)msg='Please accept the terms.';
  e.textContent=msg;if(msg)return;const em=g('re').value.trim();g('rb').disabled=true;const {error}=await sb.auth.signUp({email:em,password:g('rp').value,options:{data:{full_name:g('rn').value.trim(),requested_role:ROLES[cur.role].db}}});if(error){e.textContent=error.message;g('rb').disabled=false;return}cur.email=em;cur.mode='signup';m.close();toast('Account created. Enter the code we emailed you.','ok');location.hash='otp'}}};
/* command menu */
function cmd(){const items=[['Home','home','#landing'],...K.map(k=>['Sign in as '+ROLES[k].n,ROLES[k].i,'#login-'+k]),['Toggle theme','sun-moon','theme']];
 const m=modal(`<div style="margin:-26px"><div class="cmd" style="width:100%;box-shadow:none;border:0"><input id="cq" type="text" placeholder="Type a command…" aria-label="Command search"><div id="cl"></div></div></div>`);
 const dl=m.o.firstChild;dl.style.padding='26px';dl.style.width='min(540px,100%)';let sel=0,list=[];
 const draw=()=>{const q=$('#cq',m.o).value.toLowerCase();list=items.filter(i=>i[0].toLowerCase().includes(q));sel=Math.min(sel,Math.max(0,list.length-1));$('#cl',m.o).innerHTML=list.map((x,i)=>`<button class="${i==sel?'on':''}" data-i="${i}">${I(x[1])}${x[0]}</button>`).join('')||'<p style="padding:14px 18px;color:var(--mut)">No results.</p>';ico();$$('#cl button',m.o).forEach(b=>b.onclick=()=>run(+b.dataset.i))};
 const run=i=>{const x=list[i];if(!x)return;m.close();x[2]=='theme'?theme():location.hash=x[2]};
 $('#cq',m.o).addEventListener('input',draw);$('#cq',m.o).addEventListener('keydown',e=>{if(e.key=='ArrowDown'){sel=Math.min(sel+1,list.length-1);draw();e.preventDefault()}if(e.key=='ArrowUp'){sel=Math.max(0,sel-1);draw();e.preventDefault()}if(e.key=='Enter')run(sel)});draw()}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()=='k'){e.preventDefault();if(!$('.ov'))cmd()}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-role],[data-act],[data-dlg],[data-nav]');if(!t)return;
 if(t.dataset.role){const k=t.dataset.role;$$('.rc').forEach(c=>c.classList.add(c==t?'sel':'dim'));setTimeout(()=>location.hash='login-'+k,380)}
 else if(t.dataset.dlg)DL[t.dataset.dlg]();
 else if(t.dataset.nav)navTo(t.dataset.nav,t)
 else{const a=t.dataset.act;if(a=='theme')theme();else if(a=='cmd')cmd();else if(a=='signin'){document.getElementById('roles').scrollIntoView({behavior:'smooth'})}
 else if(a=='eye'){const p=$('#pw'),s=p.type=='password';p.type=s?'text':'password';t.innerHTML=I(s?'eye-off':'eye');ico()}
 else if(a=='out'){sb.auth.signOut().then(()=>{toast('Signed out.','ok');location.hash='landing'})}
 else if(a=='menu')$('#sd').classList.toggle('open');
 else if(a=='bell')toast('No notifications.','in')}});
window.addEventListener('hashchange',route);
/* network background */
(function(){const c=$('#net'),x=c.getContext('2d');let w,h,P=[];const rm=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function rs(){w=c.width=innerWidth;h=c.height=innerHeight;P=Array.from({length:Math.min(60,Math.floor(w*h/22000))},()=>({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25}))}
 function f(){x.clearRect(0,0,w,h);const l=document.documentElement.dataset.theme=='light';x.fillStyle=l?'rgba(80,90,200,.5)':'rgba(170,185,255,.6)';
  for(const p of P){if(!rm){p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>w)p.vx*=-1;if(p.y<0||p.y>h)p.vy*=-1}x.beginPath();x.arc(p.x,p.y,1.6,0,6.3);x.fill()}
  for(let i=0;i<P.length;i++)for(let j=i+1;j<P.length;j++){const d=Math.hypot(P[i].x-P[j].x,P[i].y-P[j].y);if(d<140){x.strokeStyle=(l?'rgba(80,90,200,':'rgba(140,150,255,')+(.2*(1-d/140))+')';x.beginPath();x.moveTo(P[i].x,P[i].y);x.lineTo(P[j].x,P[j].y);x.stroke()}}
  if(!rm)requestAnimationFrame(f)}
 addEventListener('resize',()=>{rs();rm&&f()});rs();f()})();
const isOtp=v=>new RegExp('^[0-9]{'+OTP_LENGTH+'}$').test(v);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function doLogin(em,pw){const b=$('#sb');b.disabled=true;b.innerHTML='<span class="spin"></span> Signing in…';
 try{const {data,error}=await sb.auth.signInWithPassword({email:em,password:pw});if(error)throw error;
  const {data:p}=await sb.from('profiles').select('role,account_status').eq('id',data.user.id).single();
  const deny=!p||!p.role||p.account_status!=='active'?(p&&p.account_status=='suspended'?'This account is suspended.':'Your account is awaiting administrator approval.'):p.role!==ROLES[cur.role].db?'This is not a '+ROLES[cur.role].n+' account.':'';
  if(deny||REQUIRE_EMAIL_OTP)await sb.auth.signOut({scope:'local'});
  if(deny)throw new Error(deny);
  if(!REQUIRE_EMAIL_OTP){toast('Signed in.','ok');location.hash='dash-'+cur.role;return}
  const {error:oe}=await sb.auth.signInWithOtp({email:em,options:{shouldCreateUser:false}});if(oe)throw oe;
  cur.email=em;cur.mode='email';toast('We emailed you a code.','ok');location.hash='otp'}
 catch(e){toast(e.message||'Sign in failed.','er');b.disabled=false;b.textContent='Sign In'}}
async function verifyCode(v){if(!isOtp(v)){$('#oer').textContent='The code must be exactly '+OTP_LENGTH+' digits.';return}const b=$('#ov');b.disabled=true;
 const {data,error}=await sb.auth.verifyOtp({email:cur.email,token:v,type:cur.mode=='signup'?'signup':'email'});b.disabled=false;
 if(error){$('#oer').textContent='That code is invalid or has expired.';const o=$('#ob');o.classList.remove('bad');void o.offsetWidth;o.classList.add('bad');return}
 const {data:p}=await sb.from('profiles').select('role,account_status').eq('id',data.user.id).single();
 if(!p||!p.role||p.account_status!=='active'){await sb.auth.signOut({scope:'local'});toast('Email verified. Your account is awaiting administrator approval.','ok');location.hash='landing';return}
 const k=K.find(x=>ROLES[x].db===p.role);toast('Welcome back.','ok');location.hash='dash-'+k}
async function guard(k){const {data:{session}}=await sb.auth.getSession();if(!session){toast('Please sign in first.','er');return null}
 const {data:p}=await sb.from('profiles').select('full_name,email,role,account_status').eq('id',session.user.id).single();
 if(!p||p.account_status!=='active'||p.role!==ROLES[k].db){toast('You do not have access to that area.','er');return null}p.id=session.user.id;return p}
async function loadUsers(){const el=$('#ul');if(!el)return;
 const {data,error}=await sb.from('profiles').select('id,full_name,email,role,requested_role,account_status,email_verified').order('created_at',{ascending:false});
 if(error){el.textContent=error.message;return}
 el.className='';el.style.cssText='width:100%;overflow-x:auto';
 el.innerHTML='<table style="width:100%;border-collapse:collapse;font-size:13.5px;text-align:left"><tr style="color:var(--mut)"><th style="padding:6px 8px">Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr>'+data.map(u=>{const r=u.role||u.requested_role;const act=u.id==cur.me.id?'':u.account_status=='active'?`<button class="sec" data-uid="${u.id}" data-st="suspended">Suspend</button>`:r?`<button class="sec" data-uid="${u.id}" data-st="active">Approve as ${esc(r)}</button>`:'';return `<tr style="border-top:1px solid var(--bd)"><td style="padding:12px 8px"><span style="display:flex;gap:10px;align-items:center"><span class="av" style="width:30px;height:30px;font-size:12px">${esc((u.full_name||u.email)[0]).toUpperCase()}</span><b>${esc(u.full_name||'-')}</b></span></td><td>${esc(u.email)}<div class="mut">${u.email_verified?'verified':'⚠ unverified'}</div></td><td><span class="chip2 info">${esc(u.role||'requested: '+(u.requested_role||'none'))}</span></td><td><span class="chip2 ${u.account_status=='active'?'ok':u.account_status=='pending'?'warn':'bad'}">${u.account_status}</span></td><td>${act}${u.id!=cur.me.id&&u.account_status=='active'?` <select class="sel" data-uid="${u.id}" aria-label="Change role">${DBR.map(r=>opt(r,r,u.role==r)).join('')}</select>`:''}</td></tr>`}).join('')+'</table>';
 el.onchange=async e=>{const s=e.target.closest('select[data-uid]');if(!s)return;const u=data.find(x=>x.id==s.dataset.uid);if(s.value==u.role)return;if(!confirm('Change '+(u.full_name||u.email)+' to '+s.value+'?')){s.value=u.role;return}const {error}=await sb.rpc('admin_set_role',{target:u.id,new_role:s.value,new_status:'active'});if(error){toast(error.message,'er');s.value=u.role;return}toast('Role updated.','ok');loadUsers()};
 el.onclick=async e=>{const b=e.target.closest('button[data-uid]');if(!b)return;const u=data.find(x=>x.id==b.dataset.uid);b.disabled=true;
  const {error}=await sb.rpc('admin_set_role',{target:u.id,new_role:u.role||u.requested_role,new_status:b.dataset.st});
  if(error){toast(error.message,'er');b.disabled=false;return}toast('User updated.','ok');loadUsers()}}

const CAN=()=>cur.me&&['admin','project_manager'].includes(cur.me.role);
const ST={planning:'Planning',active:'Active',on_hold:'On hold',completed:'Completed'};
const FS='width:100%;padding:12px 14px;border-radius:12px;background:var(--inp);border:1px solid var(--bd);color:var(--tx);font:inherit';
async function loadProjects(){const el=$('#pl');if(!el)return;const nb=$('#np');if(nb)nb.onclick=()=>projectForm();
 const {data,error}=await sb.from('projects').select('id,name,project_key,description,status,start_date,end_date,owner_id,project_manager_id,created_at').order('created_at',{ascending:false});
 if(error){el.textContent=error.message;return}cur.projects=data;
 if(!data.length){el.innerHTML=I('folder')+'<b>No projects yet</b><span>'+(CAN()?'Create your first project to get started.':'Projects you are added to will appear here.')+'</span>';ico();return}
 el.className='';el.style.cssText='width:100%';
 el.innerHTML=`<div class="fb" style="margin-bottom:12px"><input id="pq" type="text" placeholder="Search projects" aria-label="Search projects"><select id="pf" aria-label="Status">${opt('','All statuses',true)}${Object.entries(ST).map(([k,v])=>opt(k,v)).join('')}</select></div><div id="pg2"></div>`;
 const draw=()=>{const q=$('#pq').value.toLowerCase(),f=$('#pf').value;const v=data.filter(p=>(!f||p.status==f)&&(!q||(p.name+' '+p.project_key+' '+p.description).toLowerCase().includes(q)));
  $('#pg2').innerHTML=v.length?'<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px">'+v.map(p=>`<button class="sec" style="text-align:left;display:flex;flex-direction:column;gap:6px" data-pid="${p.id}"><span style="display:flex;justify-content:space-between;gap:8px"><b>${esc(p.name)}</b><span class="kbd">${esc(p.project_key)}</span></span><span style="color:var(--mut);font-size:13px">${esc(p.description||'No description')}</span><span style="display:flex;justify-content:space-between;align-items:center;font-size:12px;color:var(--mut)"><span class="chip2 info">${ST[p.status]}</span><span>${new Date(p.created_at).toLocaleDateString()}${p.owner_id==cur.me.id?' · yours':p.project_manager_id==cur.me.id?' · managing':''}</span></span></button>`).join('')+'</div>':'<p class="mut">No projects match.</p>'};
 $('#pq').oninput=draw;$('#pf').onchange=draw;draw();
 $('#pg2').onclick=e=>{const b=e.target.closest('[data-pid]');if(b)openProject(data.find(x=>x.id==b.dataset.pid))}}
function projectForm(p){const ed=!!p;const m=modal(`<h3>${ed?'Edit project':'New project'}</h3><label for="pn">Project name</label><input id="pn" type="text" value="${ed?esc(p.name):''}"><label for="pk">Project key</label><input id="pk" type="text" maxlength="10" placeholder="e.g. NEXUS" value="${ed?esc(p.project_key):''}" ${ed?'disabled':''}><label for="pd2">Description</label><input id="pd2" type="text" value="${ed?esc(p.description):''}"><label for="ps">Status</label><select id="ps" style="${FS}">${Object.entries(ST).map(([k,v])=>`<option value="${k}" ${ed&&p.status==k?'selected':''}>${v}</option>`).join('')}</select><div style="display:flex;gap:10px"><div style="flex:1"><label for="sd">Start date</label><input id="sd" type="date" style="${FS}" value="${ed&&p.start_date||''}"></div><div style="flex:1"><label for="ed">End date</label><input id="ed" type="date" style="${FS}" value="${ed&&p.end_date||''}"></div></div><div class="err" id="fe2"></div><div style="display:flex;gap:10px;margin-top:18px"><button class="pri" id="sv">${ed?'Save changes':'Create project'}</button><button class="sec" data-close>Cancel</button></div>`);
 const g=i=>$('#'+i,m.o);g('sv').onclick=async()=>{const e=g('fe2');const v={name:g('pn').value.trim(),description:g('pd2').value.trim(),status:g('ps').value,start_date:g('sd').value||null,end_date:g('ed').value||null};const key=g('pk').value.trim().toUpperCase();let msg='';
  if(v.name.length<3)msg='Project name must be at least 3 characters.';else if(!ed&&!/^[A-Z][A-Z0-9]{1,9}$/.test(key))msg='Key: 2 to 10 letters or digits, starting with a letter.';else if(v.start_date&&v.end_date&&v.end_date<v.start_date)msg='End date must be after the start date.';
  e.textContent=msg;if(msg)return;g('sv').disabled=true;
  const r=ed?await sb.from('projects').update(v).eq('id',p.id).select():await sb.from('projects').insert({...v,project_key:key}).select();
  g('sv').disabled=false;
  if(r.error||!r.data.length){e.textContent=r.error?(r.error.code=='23505'?'That project key is already used.':r.error.message):'You are not allowed to do that.';return}
  m.close();toast(ed?'Project updated.':'Project created.','ok');loadProjects()}}
async function openProject(p){const me=cur.me,mg=me.role=='admin'||((p.owner_id==me.id||p.project_manager_id==me.id)&&me.role=='project_manager');
 const m=modal(`<h3>${esc(p.name)} <span class="kbd">${esc(p.project_key)}</span></h3><p style="color:var(--mut);margin:6px 0">${esc(p.description||'No description')}</p><p style="font-size:13px;color:var(--mut)">${ST[p.status]}${p.start_date?' · '+p.start_date:''}${p.end_date?' to '+p.end_date:''}</p><h4 style="margin:16px 0 6px">Team</h4><div id="tm" style="font-size:13.5px;color:var(--mut)">Loading…</div><div id="pt2" class="mut"></div>${mg?`<label for="ae">Add member by email</label><div style="display:flex;gap:8px"><input id="ae" type="email" placeholder="member@company.com"><button class="sec" id="ab">Add</button></div><label for="at">Assign a team</label><div style="display:flex;gap:8px"><select id="at" style="${FS}">${(cur.teams||[]).map(t=>opt(t.id,t.name)).join('')||'<option value="">No teams yet</option>'}</select><button class="sec" id="atb">Assign</button></div>`:''}${me.role=='admin'?'<label for="pme">Assign Project Manager by email</label><div style="display:flex;gap:8px"><input id="pme" type="email" placeholder="manager@company.com"><button class="sec" id="pmb">Assign</button></div>':''}<div class="err" id="pe"></div><div style="display:flex;gap:10px;margin-top:18px;flex-wrap:wrap"><button class="pri" id="pb">Open board</button>${mg?'<button class="sec" id="pg">Edit</button><button class="sec" id="pd">Delete</button>':''}<button class="sec" data-close>Close</button></div>`);
 const g=i=>$('#'+i,m.o);
 const team=async()=>{const {data,error}=await sb.rpc('project_team',{pid:p.id});g('tm').innerHTML=error?esc(error.message):(data||[]).map(u=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0"><span>${esc(u.full_name||u.email)} · ${esc(u.role)} · ${esc(u.membership_role)}</span>${mg&&u.membership_role=='member'?`<button class="sec" data-rm="${u.user_id}">Remove</button>`:''}</div>`).join('')||'No members yet.';
  const {data:pt}=await sb.from('project_teams').select('teams(name)').eq('project_id',p.id);const tn=(pt||[]).filter(x=>x.teams).map(x=>x.teams.name);g('pt2').textContent=tn.length?'Teams: '+tn.join(', '):''};team();
 g('tm').onclick=async e=>{const b=e.target.closest('[data-rm]');if(!b)return;const {error}=await sb.from('project_members').delete().eq('project_id',p.id).eq('user_id',b.dataset.rm);if(error){g('pe').textContent=error.message;return}team()};
 g('pb').onclick=()=>{m.close();location.hash='board-'+p.id};
 const call=async(fn,args,msg,btn)=>{g('pe').textContent='';btn.disabled=true;const {error}=await sb.rpc(fn,args);btn.disabled=false;if(error){g('pe').textContent=error.message;return false}toast(msg,'ok');team();loadProjects();return true};
 if(mg){g('ab').onclick=async()=>{const em=g('ae').value.trim();if(!mailRe.test(em)){g('pe').textContent='Enter a valid email address.';return}if(await call('add_project_member',{pid:p.id,member_email:em},'Member added.',g('ab')))g('ae').value=''};
  g('atb').onclick=()=>{const t=g('at').value;if(!t){g('pe').textContent='Create a team first.';return}call('assign_team',{pid:p.id,tid:t},'Team assigned. Its members were added to the project.',g('atb'))};
  g('pg').onclick=()=>{m.close();projectForm(p)};
  let armed=false;g('pd').onclick=async()=>{if(!armed){armed=true;g('pd').textContent='Click again to confirm delete';return}const {data:d,error}=await sb.from('projects').delete().eq('id',p.id).select();if(error||!d.length){g('pe').textContent=error?error.message:'You are not allowed to delete this project.';return}m.close();toast('Project deleted.','ok');loadProjects();loadStats()}}
 if(me.role=='admin')g('pmb').onclick=async()=>{const em=g('pme').value.trim();if(!mailRe.test(em)){g('pe').textContent='Enter a valid email address.';return}if(await call('assign_project_manager',{pid:p.id,member_email:em},'Project Manager assigned.',g('pmb')))g('pme').value=''}}
/* ===== Milestone 2: tasks, sprints, Kanban, analytics ===== */
const PR={low:'#64748b',medium:'#3b82f6',high:'#f59e0b',critical:'#ef4444'};
const TS={todo:'To Do',in_progress:'In Progress',done:'Done'};
const SP=[0,1,2,3,5,8,13];
const B={p:null,sprints:[],tasks:[],team:[],sel:'all',tab:'board',q:'',pr:'',as:null};
const rk=()=>K.find(x=>ROLES[x].db===cur.me.role);
const MG=()=>B.p&&(cur.me.role=='admin'||((B.p.owner_id==cur.me.id||B.p.project_manager_id==cur.me.id)&&cur.me.role=='project_manager'));
const pts=a=>a.reduce((n,t)=>n+t.story_points,0);
const opt=(v,l,sel)=>`<option value="${v}" ${sel?'selected':''}>${esc(l)}</option>`;
async function guardAny(){const {data:{session}}=await sb.auth.getSession();if(!session){toast('Please sign in first.','er');return null}
 const {data:p}=await sb.from('profiles').select('full_name,email,role,account_status').eq('id',session.user.id).single();
 if(!p||p.account_status!=='active'||!p.role){toast('Your account is not active.','er');return null}p.id=session.user.id;return p}
function boardShell(){return `<div class="bw" style="--rc:${ROLES[rk()].c}"><div class="bar glass"><a class="ib" href="#dash-${rk()}" aria-label="Back to dashboard">${I('arrow-left')}</a><h2 id="bt">Loading…</h2><div class="tabs"><button class="tab on" data-t="board">Board</button><button class="tab" data-t="sprints">Sprints</button><button class="tab" data-t="analytics">Analytics</button></div><button class="ib" data-act="theme" aria-label="Toggle theme">${I('sun-moon')}</button></div><div id="bb"></div></div>`}
async function refresh(){const [s,t]=await Promise.all([sb.from('sprints').select('*').eq('project_id',B.p.id).order('start_date'),sb.from('tasks').select('*').eq('project_id',B.p.id).order('created_at')]);B.sprints=s.data||[];B.tasks=t.data||[];draw()}
async function loadBoard(pid){const [p,tm]=await Promise.all([sb.from('projects').select('*').eq('id',pid).maybeSingle(),sb.rpc('project_team',{pid})]);
 if(!p.data){toast('Project not found or no access.','er');location.hash='dash-'+rk();return}
 Object.assign(B,{p:p.data,team:tm.data||[],tab:B.startTab||'board',q:'',pr:'',as:null});B.startTab=null;
 $('#bt').innerHTML=esc(B.p.name)+' <span class="kbd">'+esc(B.p.project_key)+'</span>';
 $$('.tab').forEach(b=>b.onclick=()=>{B.tab=b.dataset.t;draw()});
 await refresh();const a=B.sprints.find(x=>x.status=='active');if(a){B.sel=a.id;draw()}}
function draw(){$$('.tab').forEach(b=>b.classList.toggle('on',b.dataset.t==B.tab));const bb=$('#bb');
 bb.ondragstart=e=>{const c=e.target.closest('.tk');if(c)e.dataTransfer.setData('text/plain',c.dataset.tid)};
 bb.ondragover=e=>{const c=e.target.closest('.col');if(c){e.preventDefault();c.classList.add('over')}};
 bb.ondragleave=e=>{const c=e.target.closest('.col');if(c&&!c.contains(e.relatedTarget))c.classList.remove('over')};
 bb.ondrop=e=>{const c=e.target.closest('.col');if(!c)return;e.preventDefault();c.classList.remove('over');move(e.dataTransfer.getData('text/plain'),c.dataset.st)};
 B.tab=='board'?renderBoard():B.tab=='sprints'?renderSprints():renderAnalytics();ico()}
const vis=()=>B.tasks.filter(t=>(B.sel=='all'||(B.sel=='backlog'?!t.sprint_id:t.sprint_id==B.sel))&&(!B.pr||t.priority==B.pr)&&(!B.q||(t.title+' '+t.description).toLowerCase().includes(B.q)));
const who=id=>{const u=B.team.find(x=>x.user_id==id);return u?(u.full_name||u.email):''};
function renderBoard(){const bb=$('#bb');
 bb.innerHTML=`<div class="fb"><select id="fs" aria-label="Sprint">${opt('all','All tasks',B.sel=='all')}${opt('backlog','Backlog',B.sel=='backlog')}${B.sprints.map(x=>opt(x.id,x.name+' ('+x.status+')',B.sel==x.id)).join('')}</select><input id="fq" type="text" placeholder="Search tasks" value="${esc(B.q)}"><select id="fp" aria-label="Priority">${opt('','All priorities',!B.pr)}${Object.keys(PR).map(k=>opt(k,k,B.pr==k)).join('')}</select>${MG()?'<button class="pri" id="nt">'+'New task</button>':''}</div><div id="cols"></div>`;
 $('#fs').onchange=e=>{B.sel=e.target.value;cols()};$('#fp').onchange=e=>{B.pr=e.target.value;cols()};$('#fq').oninput=e=>{B.q=e.target.value.toLowerCase();cols()};
 if(MG())$('#nt').onclick=()=>taskForm(null,'todo');cols()}
function cols(){const v=vis();$('#cols').innerHTML='<div class="kb">'+Object.keys(TS).map(st=>{const a=v.filter(t=>t.status==st);return `<div class="col glass" data-st="${st}"><h4>${TS[st]} <span class="kbd">${a.length}</span><span class="kbd">${pts(a)} pts</span>${MG()?`<button class="ib" style="margin-left:auto" data-add="${st}" aria-label="Add task to ${TS[st]}">${I('plus')}</button>`:''}</h4>${a.map(t=>`<div class="tk" tabindex="0" draggable="${MG()||t.assignee_id==cur.me.id}" data-tid="${t.id}" style="--pc:${PR[t.priority]}"><div style="display:flex;justify-content:space-between;gap:8px"><b>${esc(t.title)}</b><span class="kbd">${t.story_points} pt</span></div><div class="mut">${esc(B.p.project_key)}-${t.task_number} · ${t.priority}${t.due_date?' · due '+t.due_date:''}</div><div class="mut" style="margin-top:6px;display:flex;gap:6px;align-items:center">${t.assignee_id?`<span class="av" style="width:22px;height:22px;font-size:10px">${esc((who(t.assignee_id)||'?')[0])}</span>${esc(who(t.assignee_id))}`:'Unassigned'}${t.sprint_id?' · '+esc((B.sprints.find(x=>x.id==t.sprint_id)||{}).name||''):''}</div></div>`).join('')||'<p class="mut" style="margin-top:14px">No tasks here.</p>'}</div>`}).join('')+'</div>';ico();
 $('#cols').onclick=e=>{const a=e.target.closest('[data-add]');if(a)return taskForm(null,a.dataset.add);const c=e.target.closest('.tk');if(c)openTask(B.tasks.find(x=>x.id==c.dataset.tid))}}
async function move(id,st){const t=B.tasks.find(x=>x.id==id);if(!t||t.status==st)return;
 if(!(MG()||t.assignee_id==cur.me.id)){toast('Only the assignee or a project manager can move this task.','er');return}
 const old=t.status;t.status=st;cols();
 const {data,error}=await sb.from('tasks').update({status:st}).eq('id',id).select();
 if(error||!data.length){t.status=old;cols();toast(error?error.message:'You are not allowed to move this task.','er');return}Object.assign(t,data[0]);cols()}
function taskForm(t,st){const ed=!!t;const mem=B.team;const m=modal(`<h3>${ed?'Edit task':'New task'}</h3><label for="tt">Title</label><input id="tt" type="text" value="${ed?esc(t.title):''}"><label for="td">Description</label><input id="td" type="text" value="${ed?esc(t.description):''}"><div style="display:flex;gap:10px"><div style="flex:1"><label for="ta">Assignee</label><select id="ta" style="${FS}">${opt('','Unassigned',!ed||!t.assignee_id)}${mem.map(u=>opt(u.user_id,u.full_name||u.email,ed&&t.assignee_id==u.user_id)).join('')}</select></div><div style="flex:1"><label for="ts">Sprint</label><select id="ts" style="${FS}">${opt('','Backlog',!ed||!t.sprint_id)}${B.sprints.filter(x=>x.status!='completed').map(x=>opt(x.id,x.name,ed?t.sprint_id==x.id:B.sel==x.id)).join('')}</select></div></div><div style="display:flex;gap:10px"><div style="flex:1"><label for="tp">Priority</label><select id="tp" style="${FS}">${Object.keys(PR).map(k=>opt(k,k,ed?t.priority==k:k=='medium')).join('')}</select></div><div style="flex:1"><label for="tg">Story points</label><select id="tg" style="${FS}">${SP.map(n=>opt(n,n,ed&&t.story_points==n)).join('')}</select></div></div><div style="display:flex;gap:10px"><div style="flex:1"><label for="tx">Status</label><select id="tx" style="${FS}">${Object.entries(TS).map(([k,v])=>opt(k,v,(ed?t.status:st)==k)).join('')}</select></div><div style="flex:1"><label for="tu">Due date</label><input id="tu" type="date" style="${FS}" value="${ed&&t.due_date||''}"></div></div><div class="err" id="te"></div><div style="display:flex;gap:10px;margin-top:18px"><button class="pri" id="tv">${ed?'Save changes':'Create task'}</button><button class="sec" data-close>Cancel</button></div>`);
 const g=i=>$('#'+i,m.o);g('tv').onclick=async()=>{const v={title:g('tt').value.trim(),description:g('td').value.trim(),assignee_id:g('ta').value||null,sprint_id:g('ts').value||null,priority:g('tp').value,story_points:+g('tg').value,status:g('tx').value,due_date:g('tu').value||null};
  if(v.title.length<3){g('te').textContent='Title must be at least 3 characters.';return}g('tv').disabled=true;
  const r=ed?await sb.from('tasks').update(v).eq('id',t.id).select():await sb.from('tasks').insert({...v,project_id:B.p.id}).select();g('tv').disabled=false;
  if(r.error||!r.data.length){g('te').textContent=r.error?r.error.message:'You are not allowed to do that.';return}m.close();toast(ed?'Task updated.':'Task created.','ok');refresh()}}
function openTask(t){const can=MG()||t.assignee_id==cur.me.id;const m=modal(`<h3>${esc(t.title)} <span class="kbd">${esc(B.p.project_key)}-${t.task_number}</span></h3><p style="color:var(--mut);margin:6px 0">${esc(t.description||'No description')}</p><p class="mut">${t.priority} priority · ${t.story_points} pts${t.due_date?' · due '+t.due_date:''} · ${t.assignee_id?esc(who(t.assignee_id)):'Unassigned'}</p>${can?`<label for="os">Status</label><select id="os" style="${FS}">${Object.entries(TS).map(([k,v])=>opt(k,v,t.status==k)).join('')}</select>`:`<p class="mut">Status: ${TS[t.status]}</p>`}<h4 style="margin:16px 0 6px">History</h4><div id="oh" class="mut">Loading…</div><div class="err" id="oe2"></div><div style="display:flex;gap:10px;margin-top:18px;flex-wrap:wrap">${MG()?'<button class="pri" id="oe">Edit</button><button class="sec" id="od">Delete</button>':''}<button class="sec" data-close>Close</button></div>`);
 const g=i=>$('#'+i,m.o);
 sb.from('task_status_history').select('from_status,to_status,changed_at,changed_by').eq('task_id',t.id).order('changed_at').then(({data})=>{g('oh').innerHTML=(data||[]).map(h=>`<div>${new Date(h.changed_at).toLocaleString()}: ${h.from_status?TS[h.from_status]+' → ':'created as '}${TS[h.to_status]}${h.changed_by?' by '+esc(who(h.changed_by)||'user'):''}</div>`).join('')||'No history.'});
 if(can)g('os').onchange=async e=>{await move(t.id,e.target.value);m.close()};
 if(MG()){g('oe').onclick=()=>{m.close();taskForm(t)};let a=false;g('od').onclick=async()=>{if(!a){a=true;g('od').textContent='Click again to confirm delete';return}const {data,error}=await sb.from('tasks').delete().eq('id',t.id).select();if(error||!data.length){g('oe2').textContent=error?error.message:'Not allowed.';return}m.close();toast('Task deleted.','ok');refresh()}}}
function renderSprints(){const bb=$('#bb');
 bb.innerHTML=`<div class="fb">${MG()?'<button class="pri" id="ns">New sprint</button>':''}</div><div id="sl" style="display:grid;gap:14px"></div>`;if(MG())$('#ns').onclick=()=>sprintForm();
 $('#sl').innerHTML=B.sprints.slice().reverse().map(s=>{const ts=B.tasks.filter(t=>t.sprint_id==s.id),tot=pts(ts),dn=pts(ts.filter(t=>t.status=='done')),pc=tot?Math.round(dn/tot*100):0;
  return `<section class="tile glass" style="min-height:0"><h4 style="color:var(--tx);font-size:16px">${esc(s.name)} <span class="kbd">${s.status}</span><span style="margin-left:auto;display:flex;gap:8px">${MG()&&s.status=='planned'?`<button class="sec" data-sa="start" data-id="${s.id}">Start</button>`:''}${MG()&&s.status=='active'?`<button class="sec" data-sa="complete" data-id="${s.id}">Complete</button>`:''}${MG()&&s.status!='completed'?`<button class="sec" data-sa="edit" data-id="${s.id}">Edit</button>`:''}</span></h4><p class="mut">${esc(s.goal||'No goal set')} · ${s.start_date} to ${s.end_date}</p><div class="pbar"><i style="width:${pc}%"></i></div><p class="mut">${ts.length} tasks · ${ts.filter(t=>t.status=='done').length} done · ${dn}/${tot} points (${pc}%)</p></section>`}).join('')||`<div class="empty tile glass">${I('git-branch')}<b>No sprints yet</b><span>${MG()?'Create a sprint to start planning work.':'Sprints will appear once a project manager creates them.'}</span></div>`;ico();
 $('#sl').onclick=async e=>{const b=e.target.closest('[data-sa]');if(!b)return;const s=B.sprints.find(x=>x.id==b.dataset.id);if(b.dataset.sa=='edit')return sprintForm(s);
  b.disabled=true;const {error}=await sb.rpc(b.dataset.sa=='start'?'start_sprint':'complete_sprint',{sid:s.id});if(error){toast(error.message,'er');b.disabled=false;return}toast(b.dataset.sa=='start'?'Sprint started.':'Sprint completed. Unfinished tasks returned to the backlog.','ok');if(b.dataset.sa=='start')B.sel=s.id;refresh()}}
function sprintForm(s){const ed=!!s;const m=modal(`<h3>${ed?'Edit sprint':'New sprint'}</h3><label for="sn">Name</label><input id="sn" type="text" value="${ed?esc(s.name):''}"><label for="sg">Goal</label><input id="sg" type="text" value="${ed?esc(s.goal):''}"><div style="display:flex;gap:10px"><div style="flex:1"><label for="s1">Start date</label><input id="s1" type="date" style="${FS}" value="${ed?s.start_date:''}"></div><div style="flex:1"><label for="s2">End date</label><input id="s2" type="date" style="${FS}" value="${ed?s.end_date:''}"></div></div><div class="err" id="se"></div><div style="display:flex;gap:10px;margin-top:18px"><button class="pri" id="sv2">${ed?'Save changes':'Create sprint'}</button><button class="sec" data-close>Cancel</button></div>`);
 const g=i=>$('#'+i,m.o);g('sv2').onclick=async()=>{const v={name:g('sn').value.trim(),goal:g('sg').value.trim(),start_date:g('s1').value,end_date:g('s2').value};let msg='';
  if(v.name.length<2)msg='Sprint name is required.';else if(!v.start_date||!v.end_date)msg='Choose start and end dates.';else if(v.end_date<=v.start_date)msg='End date must be after the start date.';g('se').textContent=msg;if(msg)return;g('sv2').disabled=true;
  const r=ed?await sb.from('sprints').update(v).eq('id',s.id).select():await sb.from('sprints').insert({...v,project_id:B.p.id}).select();g('sv2').disabled=false;
  if(r.error||!r.data.length){g('se').textContent=r.error?r.error.message:'Not allowed.';return}m.close();toast(ed?'Sprint updated.':'Sprint created.','ok');refresh()}}
async function renderAnalytics(){const bb=$('#bb');const S=B.sprints;
 if(!S.length){bb.innerHTML=`<div class="empty tile glass">${I('bar-chart-3')}<b>No sprint data yet</b><span>Create a sprint and add tasks with story points to see burndown and velocity.</span></div>`;return}
 const s=S.find(x=>x.id==B.as)||S.find(x=>x.id==B.sel)||S.find(x=>x.status=='active')||S[S.length-1];B.as=s.id;
 const ts=B.tasks.filter(t=>t.sprint_id==s.id),tot=pts(ts),dn=pts(ts.filter(t=>t.status=='done')),pc=tot?Math.round(dn/tot*100):0;
 const left=Math.max(0,Math.ceil((new Date(s.end_date+'T23:59:59')-new Date())/864e5));
 const done=S.filter(x=>x.status=='completed').map(x=>({n:x.name,v:pts(B.tasks.filter(t=>t.sprint_id==x.id&&t.status=='done'))}));
 const avg=done.length?Math.round(done.reduce((a,x)=>a+x.v,0)/done.length*10)/10:0,mx=Math.max(1,...done.map(x=>x.v));
 bb.innerHTML=`<div class="fb"><select id="as" aria-label="Sprint">${S.map(x=>opt(x.id,x.name+' ('+x.status+')',x.id==s.id)).join('')}</select></div><div class="stats"><div class="stat"><span class="mut">Total points</span><b>${tot}</b></div><div class="stat"><span class="mut">Completed</span><b>${dn}</b></div><div class="stat"><span class="mut">Remaining</span><b>${tot-dn}</b></div><div class="stat"><span class="mut">Progress</span><b>${pc}%</b></div><div class="stat"><span class="mut">Days left</span><b>${s.status=='completed'?'-':left}</b></div></div><section class="tile glass" style="min-height:0"><h4>${I('trending-down')}Burndown</h4><div id="bd" class="mut">Loading…</div></section><section class="tile glass" style="min-height:0"><h4>${I('gauge')}Velocity${done.length?' · average '+avg+' pts':''}</h4>${done.length?`<div style="display:flex;gap:14px;align-items:flex-end;height:160px;padding-top:10px">${done.map(x=>`<div style="flex:1;text-align:center"><div class="mut">${x.v}</div><div style="height:${Math.max(4,x.v/mx*110)}px;border-radius:8px 8px 0 0;background:linear-gradient(180deg,#8b5cf6,#3b82f6)"></div><div class="mut">${esc(x.n)}</div></div>`).join('')}</div>`:`<div class="empty">${I('gauge')}<b>No completed sprints yet</b><span>Velocity appears after you complete a sprint.</span></div>`}</section>`;ico();
 $('#as').onchange=e=>{B.as=e.target.value;renderAnalytics()};
 if(!tot){$('#bd').innerHTML='<div class="empty">'+I('trending-down')+'<b>No story points in this sprint</b><span>Assign tasks with story points to see the burndown.</span></div>';ico();return}
 const ids=ts.map(t=>t.id);const {data:h}=await sb.from('task_status_history').select('task_id,to_status,changed_at').in('task_id',ids).order('changed_at');
 const days=[];for(let d=new Date(s.start_date+'T00:00:00');d<=new Date(s.end_date+'T00:00:00');d.setDate(d.getDate()+1))days.push(new Date(d));
 const N=days.length,now=new Date();const ideal=days.map((_,i)=>N>1?tot*(1-i/(N-1)):0);
 const actual=days.map(d=>{if(d>now)return null;const e=new Date(d);e.setHours(23,59,59,999);let dd=0;for(const t of ts){let l=null;for(const x of h||[])if(x.task_id==t.id&&new Date(x.changed_at)<=e)l=x.to_status;if(l=='done')dd+=t.story_points}return tot-dd});
 const W=640,H=250,P=38,X=i=>P+i*(W-2*P)/Math.max(1,N-1),Y=v=>H-P-v/tot*(H-2*P);
 const line=a=>a.map((v,i)=>v==null?null:X(i)+','+Y(v)).filter(Boolean).join(' ');
 $('#bd').innerHTML=`<div style="overflow-x:auto"><svg viewBox="0 0 ${W} ${H}" style="width:100%;min-width:420px" role="img" aria-label="Burndown chart"><line x1="${P}" y1="${H-P}" x2="${W-P}" y2="${H-P}" stroke="var(--bd)"/><line x1="${P}" y1="${P}" x2="${P}" y2="${H-P}" stroke="var(--bd)"/><text x="6" y="${P+4}" fill="var(--mut)" font-size="11">${tot}</text><text x="14" y="${H-P+4}" fill="var(--mut)" font-size="11">0</text>${days.map((d,i)=>(N<=14||i%Math.ceil(N/14)==0)?`<text x="${X(i)}" y="${H-14}" fill="var(--mut)" font-size="10" text-anchor="middle">${d.getDate()}</text>`:'').join('')}<polyline points="${line(ideal)}" fill="none" stroke="var(--mut)" stroke-width="2" stroke-dasharray="6 5"/><polyline points="${line(actual)}" fill="none" stroke="var(--rc)" stroke-width="3"/></svg></div><p class="mut">Dashed: ideal remaining points. Solid: actual remaining points from task history (x-axis: day of month).</p>`}

function navTo(n,t){$$('.ni').forEach(x=>x.classList.toggle('on',x==t));const sd=$('#sd');sd&&sd.classList.remove('open');
 if(n=='Dashboard')return scrollTo({top:0,behavior:'smooth'});
 if(n=='Projects')return $('#pt').scrollIntoView({behavior:'smooth'});
 if(n=='Teams'){const t=$('#tmt');return t?t.scrollIntoView({behavior:'smooth'}):0}
 if(n=='Users'){const u=$('#ul');return u?u.scrollIntoView({behavior:'smooth'}):toast('Users are managed by admins.','in')}
 if(n=='Settings')return settings();
 const tab={Tasks:'board',Kanban:'board',Sprints:'sprints',Analytics:'analytics'}[n];const ps=cur.projects||[];
 if(!ps.length)return toast('Create or join a project first.','in');
 const go=p=>{B.startTab=tab;location.hash='board-'+p.id};if(ps.length==1)return go(ps[0]);
 const m=modal('<h3>Choose a project</h3>'+ps.map(p=>`<button class="sec" style="display:block;width:100%;text-align:left;margin-top:10px" data-p="${p.id}">${esc(p.name)} <span class="kbd">${esc(p.project_key)}</span></button>`).join(''));
 m.o.addEventListener('click',e=>{const b=e.target.closest('[data-p]');if(b){m.close();go(ps.find(x=>x.id==b.dataset.p))}})}
function settings(){const m=modal(`<h3>Settings</h3><p class="mut" style="margin:6px 0 14px">${esc(cur.me.full_name||'')} · ${esc(cur.me.email)} · ${esc(cur.me.role)}</p><div style="display:flex;gap:10px"><button class="sec" id="st1">Toggle theme</button><button class="sec" data-close>Close</button></div>`);$('#st1',m.o).onclick=theme}

const DBR=['admin','project_manager','developer','tester','devops'];
async function loadStats(){const el=$('#stt');if(!el)return;const c=async(t,f)=>{let q=sb.from(t).select('id',{count:'exact',head:true});if(f)q=f(q);const {count}=await q;return count??0};
 const [pr,ac,tm]=await Promise.all([c('projects'),c('projects',q=>q.eq('status','active')),c('teams')]);let adm='';
 if(cur.me.role=='admin'){const [us,pe]=await Promise.all([c('profiles'),c('profiles',q=>q.eq('account_status','pending'))]);adm=`<div class="stat"><span class="mut">Registered users</span><b>${us}</b></div><div class="stat"><span class="mut">Pending approval</span><b>${pe}</b></div>`}
 el.innerHTML=`<div class="stat"><span class="mut">Projects</span><b>${pr}</b></div><div class="stat"><span class="mut">Active projects</span><b>${ac}</b></div><div class="stat"><span class="mut">Teams</span><b>${tm}</b></div>`+adm}
async function loadRoles(){const el=$('#rpl');if(!el)return;const {data,error}=await sb.from('roles').select('role_name,description,role_permissions(permissions(permission_name))').order('id');
 if(error){el.textContent=error.message;return}el.className='';el.style.cssText='width:100%';
 el.innerHTML=data.map(r=>`<div style="padding:10px 0;border-top:1px solid var(--bd)"><b>${esc(r.role_name)}</b> <span class="mut">${esc(r.description)}</span><div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap">${r.role_permissions.map(x=>`<span class="chip2 info">${esc(x.permissions.permission_name)}</span>`).join('')}</div></div>`).join('')+'<p class="mut">These describe each role. They are enforced by the database security rules.</p>'}
async function loadTeams(){const el=$('#tl');if(!el)return;const nb=$('#nteam');if(nb)nb.onclick=()=>teamForm();
 const {data,error}=await sb.from('teams').select('id,name,description,created_by,team_members(count)').order('name');
 if(error){el.textContent=error.message;return}cur.teams=data;
 if(!data.length){el.innerHTML=I('network')+'<b>No teams yet</b><span>Create teams such as Backend, Frontend, QA or DevOps.</span>';ico();return}
 el.className='';el.style.cssText='width:100%';
 el.innerHTML='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px">'+data.map(t=>`<button class="sec" style="text-align:left;display:flex;flex-direction:column;gap:6px" data-tid="${t.id}"><b>${esc(t.name)}</b><span class="mut">${esc(t.description||'No description')}</span><span class="chip2 info" style="align-self:flex-start">${t.team_members[0].count} members</span></button>`).join('')+'</div>';
 el.onclick=e=>{const b=e.target.closest('[data-tid]');if(b)openTeam(data.find(x=>x.id==b.dataset.tid))}}
function teamForm(){const m=modal(`<h3>New team</h3><label for="tn">Name</label><input id="tn" type="text" placeholder="e.g. Backend"><label for="tdsc">Description</label><input id="tdsc" type="text"><div class="err" id="tre"></div><div style="display:flex;gap:10px;margin-top:18px"><button class="pri" id="tsv">Create team</button><button class="sec" data-close>Cancel</button></div>`);
 const g=i=>$('#'+i,m.o);g('tsv').onclick=async()=>{const n=g('tn').value.trim();if(n.length<2){g('tre').textContent='Team name must be at least 2 characters.';return}g('tsv').disabled=true;
  const {data,error}=await sb.from('teams').insert({name:n,description:g('tdsc').value.trim()}).select();g('tsv').disabled=false;
  if(error||!data.length){g('tre').textContent=error?(error.code=='23505'?'That team name already exists.':error.message):'Not allowed.';return}m.close();toast('Team created.','ok');loadTeams();loadStats()}}
async function openTeam(t){const mg=cur.me.role=='admin'||t.created_by==cur.me.id;
 const m=modal(`<h3>${esc(t.name)}</h3><p class="mut" style="margin:6px 0">${esc(t.description||'No description')}</p><h4 style="margin:14px 0 6px">Members</h4><div id="tr" class="mut">Loading…</div>${mg?'<label for="tae">Add member by email</label><div style="display:flex;gap:8px"><input id="tae" type="email"><button class="sec" id="tab">Add</button></div>':''}<div class="err" id="ter"></div><div style="display:flex;gap:10px;margin-top:18px">${mg?'<button class="sec" id="tdl">Delete team</button>':''}<button class="sec" data-close>Close</button></div>`);
 const g=i=>$('#'+i,m.o);
 const roster=async()=>{const {data,error}=await sb.rpc('team_roster',{tid:t.id});g('tr').innerHTML=error?esc(error.message):(data||[]).map(u=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0"><span>${esc(u.full_name||u.email)} <span class="chip2 info">${esc(u.role)}</span></span>${mg?`<button class="sec" data-rm="${u.user_id}">Remove</button>`:''}</div>`).join('')||'No members yet.'};roster();
 g('tr').onclick=async e=>{const b=e.target.closest('[data-rm]');if(!b)return;const {error}=await sb.from('team_members').delete().eq('team_id',t.id).eq('user_id',b.dataset.rm);if(error){g('ter').textContent=error.message;return}roster();loadTeams()};
 if(mg){g('tab').onclick=async()=>{g('ter').textContent='';const em=g('tae').value.trim();if(!mailRe.test(em)){g('ter').textContent='Enter a valid email address.';return}const {error}=await sb.rpc('team_add_member',{tid:t.id,member_email:em});if(error){g('ter').textContent=error.message;return}g('tae').value='';roster();loadTeams()};
  let a=false;g('tdl').onclick=async()=>{if(!a){a=true;g('tdl').textContent='Click again to confirm delete';return}const {data,error}=await sb.from('teams').delete().eq('id',t.id).select();if(error||!data.length){g('ter').textContent=error?error.message:'Not allowed.';return}m.close();toast('Team deleted.','ok');loadTeams();loadStats()}}}

route();
